// Settings APPLY path (conversion table). Maps each of the 140 menu items to an apply
// route + value encoding. The table (src/model/apply_gen.cpp) is GENERATED by
// uicore/tools/gen_apply.py from app/docs/settings_sdcom_map.tsv + the documented RE
// maps (re/static/bkid_whitelist.md, TRACKB_INPROCESS.md); nothing here is invented:
// anything without RE data is AM_UNMAPPED. Zero platform includes: executing a route
// is the platform adapter's job (CameraControl::applySetting).
#pragma once

namespace uicore {

// Primary classification of a menu item (one per item; routes[] may list several).
enum ApplyMethod {
    AM_LOCAL = 0,   // app-side preference / read-only info: no engine apply
    AM_ACTION,      // gated action / playback / quick slot: not a value apply
    AM_INPROC,      // standard engine path proven in-process (requestModelExecute / engine vtable)
    AM_SDCOM,       // SDCom 0x1003 paramId + A-side value (map data exists; executor = SDCom platform)
    AM_BACKUP,      // native-only: Backup propId recorded, NOT written (runtime-only task)
    AM_UNMAPPED     // no mapping data -> [unmapped], never guessed
};
enum ApplyRoute { AR_INPROC = 1, AR_SDCOM = 2, AR_BACKUP = 4 };
enum ApplyEnc   { AE_NONE = 0, AE_OPT = 1 /* option index -> table */, AE_INT = 2 /* number as-is */ };
enum InprocKind {
    IK_NONE = 0,
    IK_ASPECT = 1, /* CmnViewProcessDataMgr group 1 (TRACKB §18) -- kept for back-compat */
    IK_GROUP  = 2  /* CmnViewProcessDataMgr group `inprocGroup` (TRACKB §23): write
                      vtable[14](obj,group,internalVal), read-back vtable[3] */
};

enum { APPLY_UNMAPPED_VAL = -0x7fffffff };

// Result of CameraControl::applySetting.
enum ApplyResult {
    APPLY_OK = 0,       // applied (and read back where the platform can)
    APPLY_REJECTED,     // route exists, engine refused / read-back mismatch / guarded
    APPLY_NO_ROUTE,     // mapped, but this platform has no executor for the route
    APPLY_UNMAPPED,     // no RE data for this item / this value
    APPLY_LOCAL,        // app-local item: nothing for the engine to do
    APPLY_RECORDED      // Backup propId known but deliberately not written
};

struct ApplyEntry {
    const char *key;        // MenuItem key
    unsigned char method;   // ApplyMethod
    unsigned char routes;   // ApplyRoute bitmask
    unsigned char enc;      // ApplyEnc (for the SDCom/catalog value)
    unsigned char inproc;   // InprocKind
    short inprocGroup;      // IK_GROUP: CmnViewProcessDataMgr group number (0 = none)
    short catalogId;        // uicore SettingId bridge (0 = none)
    short sdcomParam;       // SDCom paramId (0 = none)
    short sdcomMsg;         // SDCom message id carrying it (0x1003 CameraSetParameters; 0x300a MovieSetParameters)
    int   backupProp;       // Backup propId (0 = none; recorded only)
    const int *sdcomVals;   // AE_OPT: per-option A-side value (APPLY_UNMAPPED_VAL = no data)
    const int *inprocVals;  // IK_*: per-option engine value (APPLY_UNMAPPED_VAL = no data)
    const char *note;
};

extern const ApplyEntry kApply[140];   // index == kMenuItems index

// A resolved command: everything an executor needs, no strings to parse.
struct ApplyCmd {
    int item, method, routes;
    int catalogId, catalogValue;        // catalog bridge (A-side == SDCom value)
    int sdcomParam, sdcomMsg, sdcomValue;   // sdcomValue valid iff sdcomOk
    bool sdcomOk;
    int backupProp;
    int inprocKind, inprocGroup, inprocValue;   // inprocValue valid iff inprocOk
    bool inprocOk;
};

// value: option index for enumerated items, the number itself for MT_RANGE.
// false = item/value out of range. Never touches the engine.
bool applyResolve(int item, int value, ApplyCmd *out);
const char *applyMethodName(int method);

} // namespace uicore
